public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Create a visited array to keep track of the n-tersections that have been visited
    boolean[] visited = new boolean[n];

    // Initialize the visited array and the queue with the starting n-tersection
    visited[start[0]] = true;
    Queue<int[]> queue = new LinkedList<>();
    queue.add(start);

    // Loop until the queue is empty
    while (!queue.isEmpty()) {
        // Get the current n-tersection and its coordinates
        int[] current = queue.remove();
        int x = current[0];
        int y = current[1];

        // If the current n-tersection is the ending n-tersection, return "can be travelled"
        if (x == end[0] && y == end[1]) {
            return "can be travelled";
        }

        // Loop through the paths between adjacent n-tersections
        for (int[] path : paths) {
            // If the current n-tersection is a path starting n-tersection, get the path end n-tersection
            if (x == path[0] && y == path[1]) {
                int[] end = new int[]{path[2], path[3]};

                // If the end n-tersection has not been visited, mark it as visited and add it to the queue
                if (!visited[end[0]]) {
                    visited[end[0]] = true;
                    queue.add(end);
                }
            }
        }
    }

    // If the queue is empty and the ending n-tersection has not been visited, return "cannot be travelled"
    if (!visited[end[0]]) {
        return "cannot be travelled";
    }

    // Return "cannot be travelled" otherwise
    return "cannot be travelled";
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Initialize a 2D array to represent the n-teresting space
    boolean[][] maze = new boolean[n][n];

    // Fill in the 2D array with the paths between adjacent n-tersections
    for (int[] path : paths) {
        maze[path[0]][path[1]] = true;
    }

    // Use DFS to check if the maze can be travelled from the starting n-tersection to the ending n-tersection
    if (canTravelMazeDFS(maze, start, end)) {
        return "can be travelled";
    } else {
        return "cannot be travelled";
    }
}

private static boolean canTravelMazeDFS(boolean[][] maze, int[] start, int[] end) {
    // Base case: if the current n-tersection is the ending n-tersection, return true
    if (start[0] == end[0] && start[1] == end[1]) {
        return true;
    }

    // Check if the current n-tersection is valid
    if (start[0] < 0 || start[0] >= maze.length || start[1] < 0 || start[1] >= maze[0].length || !maze[start[0]][start[1]]) {
        return false;
    }

    // Mark the current n-tersection as visited
    maze[start[0]][start[1]] = false;

    // Recursively explore the maze starting from the current n-tersection
    for (int i = 0; i < 4; i++) {
        int[] newStart = getNextNtersection(start, i);
        if (canTravelMazeDFS(maze, newStart, end)) {
            return true;
        }
    }

    // If no path is found, return false
    return false;
}

private static int[] getNextNtersection(int[] start, int direction) {
    // Use the direction to get the next n-tersection in the maze
    switch (direction) {
        case 0:
            // North
            return new int[]{start[0] - 1, start[1]};
        case 1:
            // East
            return new int[]{start[0], start[1] + 1};
        case 2:
            // South
            return new int[]{start[0] + 1, start[1]};
        case 3:
            // West
            return new int[]{start[0], start[1] - 1};
    }
    return null;
}

