public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Create a boolean array to store the visits of each n-tersection
    boolean[] visited = new boolean[n];

    // Initialize the starting n-tersection as visited
    visited[start[0] * n + start[1]] = true;

    // Create a queue to store the next stages of n-tersections to visit
    Queue<int[]> queue = new LinkedList<>();

    // Enqueue the starting n-tersection
    queue.offer(start);

    // Loop until the queue is empty
    while (!queue.isEmpty()) {
        // Dequeue the next n-tersection to visit
        int[] current = queue.poll();

        // Check if the current n-tersection is the ending n-tersection
        if (current[0] == end[0] && current[1] == end[1]) {
            // If so, return "can be travelled"
            return "can be travelled";
        }

        // Loop through the paths of the current n-tersection
        for (int[] path : paths) {
            // Calculate the index of the next n-tersection
            int next = path[0] * n + path[1];

            // If the next n-tersection has not been visited, mark it as visited and enqueue it
            if (!visited[next]) {
                visited[next] = true;
                queue.offer(path);
            }
        }
    }

    // If the queue is empty and the ending n-tersection has not been visited, return "cannot be travelled"
    if (!visited[end[0] * n + end[1]]) {
        return "cannot be travelled";
    }

    // Otherwise, return "can be travelled"
    return "can be travelled";
}

