public int minTime(int n, int[][] edges, boolean[] hasApple) {
    // Initialize a queue to store the nodes to be processed
    Queue<Integer> queue = new LinkedList<>();

    // Initialize a visited array to keep track of the nodes that have been visited
    boolean[] visited = new boolean[n];

    // Initialize the minimum time required to collect all the apples and return to node 0
    int minTime = 0;

    // Mark the starting node as visited
    visited[0] = true;

    // Add the starting node to the queue
    queue.offer(0);

    // Loop until the queue is empty
    while (!queue.isEmpty()) {
        // Get the current node from the queue
        int currentNode = queue.poll();

        // If the current node has an apple, increase the minimum time required
        if (hasApple[currentNode]) {
            minTime++;
        }

        // Loop through the edges of the current node
        for (int[] edge : edges) {
            // If the edge is not a self-loop and the node has not been visited, mark it as visited and add it to the queue
            if (edge[0] != edge[1] && !visited[edge[1]]) {
                visited[edge[1]] = true;
                queue.offer(edge[1]);
            }
        }
    }

    // Return the minimum time required to collect all the apples and return to node 0
    return minTime;
}

public static int minTime(int n, int[][] edges, boolean[] hasApple) {
    // Initialize a queue to store the nodes to be traversed
    Queue<Integer> queue = new LinkedList<>();

    // Add node 0 to the queue
    queue.offer(0);

    // Initialize a variable to store the minimum time
    int minTime = 0;

    // Loop until the queue is empty
    while (!queue.isEmpty()) {
        // Get the current node from the queue
        int node = queue.poll();

        // If the current node has an apple, increment the minimum time
        if (hasApple[node]) {
            minTime++;
        }

        // Loop through the edges of the current node
        for (int[] edge : edges) {
            // Get the adjacent node
            int adjacentNode = edge[node == edge[0] ? 1 : 0];

            // If the adjacent node has not been visited, add it to the queue
            if (!queue.contains(adjacentNode)) {
                queue.offer(adjacentNode);
            }
        }
    }

    // Return the minimum time required to collect all the apples and return to node 0
    return minTime;
}

public String sortString(String s) {
    char[] chars = s.toCharArray();
    Arrays.sort(chars);
    String result = "";
    while (chars.length > 0) {
        // pick the smallest character
        char smallest = chars[0];
        result += smallest;
        chars = Arrays.copyOfRange(chars, 1, chars.length);

        // pick the smallest character greater than the last appended character
        char[] remaining = Arrays.copyOfRange(chars, 0, chars.length);
        Arrays.sort(remaining);
        char found = '\0';
        for (int i = 0; i < remaining.length; i++) {
            if (remaining[i] > smallest) {
                found = remaining[i];
                break;
            }
        }
        if (found != '\0') {
            result += found;
            chars = Arrays.copyOfRange(chars, 1, chars.length);
        }

        // pick the largest character
        char largest = chars[chars.length - 1];
        result += largest;
        chars = Arrays.copyOfRange(chars, 0, chars.length - 1);

        // pick the largest character smaller than the last appended character
        remaining = Arrays.copyOfRange(chars, 0, chars.length);
        Arrays.sort(remaining);
        found = '\0';
        for (int i = remaining.length - 1; i >= 0; i--) {
            if (remaining[i] < largest) {
                found = remaining[i];
                break;
            }
        }
        if (found != '\0') {
            result += found;
            chars = Arrays.copyOfRange(chars, 0, chars.length - 1);
        }
    }
    return result;
}

