        int maxIndex = -1;
        for (int i = 0; i < s.length(); i++) {
            if (maxChar < s.charAt(i)) {
                maxChar = s.charAt(i);
                maxIndex = i;
            }
        }
        result += maxChar;
        s = s.substring(0, maxIndex) + s.substring(maxIndex + 1);

        // Step 5: Pick the largest character from s which is smaller than the last appended character to the result and append it.
        char maxSmallerChar = Character.MAX_VALUE;
        int maxSmallerIndex = -1;
        for (int i = 0; i < s.length(); i++) {
            if (maxSmallerChar < s.charAt(i) && s.charAt(i) < result.charAt(result.length() - 1)) {
                maxSmallerChar = s.charAt(i);
                maxSmallerIndex = i;
            }
        }
        if (maxSmallerIndex != -1) {
            result += maxSmallerChar;
            s = s.substring(0, maxSmallerIndex) + s.substring(maxSmallerIndex + 1);
        }

        // Step 6: Repeat step 5 until you cannot pick more characters.
        while (maxSmallerIndex != -1) {
            maxSmallerChar = Character.MAX_VALUE;
            maxSmallerIndex = -1;
            for (int i = 0; i < s.length(); i++) {
                if (maxSmallerChar < s.charAt(i) && s.charAt(i) < result.charAt(result.length() - 1)) {
                    maxSmallerChar = s.charAt(i);
                    maxSmallerIndex = i;
                }
            }
            if (maxSmallerIndex != -1) {
                result += maxSmallerChar;
                s = s.substring(0, maxSmallerIndex) + s.substring(maxSmallerIndex + 1);
            }
        }
    }
    return result;
}

public boolean splitArraySameAverage(int[] nums) {
    if (nums.length == 1) {
        return false;
    }
    int sum = Arrays.stream(nums).sum();
    int avg = sum / nums.length;
    int leftSum = 0;
    for (int i = 0; i < nums.length; i++) {
        leftSum += nums[i];
        if (leftSum == sum - leftSum) {
            return true;
        }
    }
    return false;
}

public boolean splitArraySameAverage(int[] nums) {
    int sum = 0;
    for (int num : nums) {
        sum += num;
    }
    int n = nums.length;
    int avg = sum / n;
    int sum1 = 0;
    int sum2 = 0;
    for (int i = 0; i < n - 1; i++) {
        sum1 += nums[i];
        sum2 += nums[i + 1];
        if (sum1 == sum2) {
            return true;
        }
        if (sum1 > avg && sum2 > avg) {
            return false;
        }
    }
    return false;
}

public boolean splitArraySameAverage(int[] nums) {
    int sum = 0;
    for (int num : nums) {
        sum += num;
    }
    if (sum % 2 != 0) {
        return false;
    }
    int target = sum / 2;
    return subsetSum(nums, target);
}

private boolean subsetSum(int[] nums, int target) {
    if (nums.length == 0) {
        return false;
    }
    if (nums[0] == target) {
        return true;
    }
    if (nums[0] > target) {
        return false;
    }
    return subsetSum(Arrays.copyOfRange(nums, 1, nums.length), target - nums[0]) ||
           subsetSum(Arrays.copyOfRange(nums, 1, nums.length), target);
}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n % 2 == 1) return false;
    int sum = 0;
    for (int num : nums) sum += num;
    int avg = sum / n;
    if (sum % n != 0) return false;
    int count = 0;
    int[] arr = new int[n / 2];
    for (int i = 0; i < n / 2; i++) {
        arr[i] = nums[i];
        count += nums[i];
    }
    if (count == avg * n / 2) {
        for (int i = n / 2; i < n; i++) {
            if (arr[i - n / 2] != nums[i]) return false;
        }
        return true;
    }
    return false;
}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n % 2 == 1) return false;
    int sum = 0;
    for (int i = 0; i < n; i++) {
        sum += nums[i];
    }
    int halfSum = sum / 2;
    int[] prefixSums = new int[n + 1];
    for (int i = 0; i < n; i++) {
        prefixSums[i + 1] = prefixSums[i] + nums[i];
    }
    for (int i = 1; i <= n / 2; i++) {
        int left = i;
        int right = n - i;
        if (prefixSums[left] == halfSum && prefixSums[right] == halfSum) return true;
        int leftSum = prefixSums[left] - prefixSums[0];
        int rightSum = prefixSums[n] - prefixSums[right];
        if (leftSum == rightSum) return true;
    }
    return false;
}

public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    if (n == 0) return 0;
    if (n == 1) return cost[0];
    if (n == 2) return Math.min(cost[0], cost[1]);
    int[] dp = new int[n];
    dp[0] = cost[0];
    dp[1] = cost[1];
    dp[2] = Math.min(cost[0], cost[1]);
    for (int i = 3; i < n; i++) {
        dp[i] = Math.min(dp[i - 1], dp[i - 2]) + cost[i];
    }
    return Math.min(dp[n - 1], dp[n - 2]);
}

