}

public int minOperations(int n) {
    int[] arr = new int[n];
    for (int i = 0; i < n; i++) {
        arr[i] = (2 * i) + 1;
    }
    int operations = 0;
    while (Arrays.stream(arr).distinct().count() > 1) {
        int largest = Arrays.stream(arr).max().getAsInt();
        int smallest = Arrays.stream(arr).min().getAsInt();
        if (largest - smallest > 1) {
            int x = 0;
            int y = 0;
            while (arr[x] == largest) {
                x++;
            }
            while (arr[y] == smallest) {
                y++;
            }
            arr[x]--;
            arr[y]++;
            operations++;
        } else {
            break;
        }
    }
    return operations;
}

public int minOperations(int n) {
    int operations = 0;
    for (int i = 0; i < n; i++) {
        int diff = (2 * i) + 1 - n;
        operations += diff;
    }
    return operations;
}

public int minOperations(int n) {
