public int findMinFibonacciNumbers(int k) {
    int count = 0;
    int n1 = 1, n2 = 1, next;
    while (n1 + n2 < k) {
        next = n1 + n2;
        n1 = n2;
        n2 = next;
        count++;
    }
    return count;
}

public int findMinFibonacciNumbers(int k) {
    int fib1 = 1, fib2 = 1, fib = 0;
    while (fib < k) {
        fib = fib1 + fib2;
        fib1 = fib2;
        fib2 = fib;
    }
    int minFibonacciNumbers = 0;
    while (fib >= k) {
        if (fib == k) {
            return minFibonacciNumbers + 1;
        }
        fib -= k;
        minFibonacciNumbers++;
    }
    return minFibonacciNumbers;
}

public int findMinFibonacciNumbers(int k) {
    int[] fibonacciSequence = new int[k];
    fibonacciSequence[0] = 0;
    fibonacciSequence[1] = 1;
    int minFibonacciNumbers = 0;
    for (int i = 2; i < k; i++) {
        fibonacciSequence[i] = fibonacciSequence[i - 1] + fibonacciSequence[i - 2];
        if (fibonacciSequence[i] > k) {
            minFibonacciNumbers++;
        }
    }
    return minFibonacciNumbers;
}

public int findMinFibonacciNumbers(int k) {
