    int n1 = 1, n2 = 1;
    while (n1 + n2 < k) {
        int sum = n1 + n2;
        n1 = n2;
        n2 = sum;
        count++;
    }
    return count;
}

public int findMinFibonacciNumbers(int k) {
    int fib1 = 1, fib2 = 1, fib3 = 2;
    int minFibonacciNumbers = 0;
    while (fib3 <= k) {
        if (k >= fib1 + fib3) {
            k -= fib3;
            minFibonacciNumbers++;
        } else if (k >= fib1 + fib2) {
            k -= fib1;
            minFibonacciNumbers++;
        } else {
            k -= fib2;
            minFibonacciNumbers++;
        }
        int temp = fib1;
        fib1 = fib2;
        fib2 = fib3;
        fib3 = temp + fib2;
    }
    return minFibonacciNumbers;
}

public int kthFactor(int n, int k) {
    ArrayList<Integer> factors = new ArrayList<>();

    for (int i = 1; i <= n; i++) {
        if (n % i == 0) {
            factors.add(i);
        }
    }

    if (factors.size() < k) {
        return -1;
    } else {
        return factors.get(k - 1);
    }
}

