        if (i == 0 || chars[i] != Character.toLowerCase(chars[i - 1])) {
            sb.append(chars[i]);
        } else if (i > 0 && chars[i] == Character.toLowerCase(chars[i - 1]) && sb.charAt(sb.length() - 1) == Character.toUpperCase(chars[i])) {
            // Remove adjacent lowercase and uppercase characters that are opposite each other
            sb.deleteCharAt(sb.length() - 1);
            // Remove the current char if it is the same as the previous char
            if (i < chars.length - 1 && chars[i] == chars[i + 1]) {
                i++;
            }
        }
    }
    return sb.toString();
}

