public int maxUniqueSplit(String s) {
    int n = s.length();
    int[][] dp = new int[n][n];
    int count = 0;
    for (int i = 0; i < n; i++) {
        for (int j = i; j < n; j++) {
            if (s.charAt(i) == s.charAt(j)) {
                dp[i][j] = dp[i + 1][j - 1] + 2;
                count = Math.max(count, dp[i][j]);
            } else {
                dp[i][j] = Math.max(dp[i][j - 1], dp[i + 1][j]);
            }
        }
    }
    return count;
}

