public String getSmallestString(int n, int k) {
    char[] alphabet = "abcdefghijklmnopqrstuvwxyz".toCharArray();
    StringBuilder sb = new StringBuilder();
    while (k > 0 && n > 0) {
        int pos = k % 26;
        sb.append(alphabet[pos - 1]);
        k /= 26;
        n--;
    }
    while (n > 0) {
        sb.append('a');
        n--;
    }
    return sb.reverse().toString();
}

public String getSmallestString(int n, int k) {
    // Initialize variables
    int idx = 0;
    char[] chars = new char[n];
    int[] positions = new int[26];

    // Initialize positions array
    for (int i = 0; i < 26; i++) {
        positions[i] = i + 1;
    }

    // Fill the characters array
    for (int i = 0; i < n; i++) {
        chars[i] = (char) (idx + 'a');
        idx++;
        if (idx == 26) {
            idx = 0;
        }
    }

    // Find the smallest string
    while (true) {
        int sum = 0;
        for (int i = 0; i < n; i++) {
            sum += positions[chars[i] - 'a'];
        }
        if (sum == k) {
            break;
        }
        if (sum > k) {
            for (int i = n - 1; i >= 0; i--) {
                if (chars[i] != 'a') {
                    chars[i]--;
                    break;
                } else {
                    chars[i] = 'z';
                }
            }
        } else {
            for (int i = n - 1; i >= 0; i--) {
                if (chars[i] != 'z') {
                    chars[i]++;
                    break;
                } else {
                    chars[i] = 'a';
                }
            }
        }
    }

    // Return the smallest string
    return new String(chars);
}

public String getSmallestString(int n, int k) {
    // Create a char array to store the result
    char[] result = new char[n];

    // Set the first character of the result to the character that corresponds to the value of k
    result[0] = (char) (k + 'a' - 1);

    // Iterate over the remaining characters of the result
    for (int i = 1; i < n; i++) {
      // Calculate the value of the current character based on the previous character and the value of k
      int currVal = (result[i - 1] - 'a' + 1) % 26 + k;

      // Set the current character of the result to the character that corresponds to the calculated value
      result[i] = (char) (currVal + 'a' - 1);
    }

    // Return the result as a string
    return new String(result);
  }

public String getSmallestString(int n, int k) {
    StringBuilder sb = new StringBuilder();
    int rem = k;
    for (int i = 0; i < n; i++) {
        int curr = Math.min(rem, 26);
        sb.append((char)('a' + curr));
        rem -= curr;
    }
    return sb.toString();
}

