public double calculateProbability(int n) {
    int totalSeats = n + 1; // Including the driver's seat
    int passengerSeats = n;
    int emptySeats = totalSeats - passengerSeats;

    // Permutations of the passenger seats
    long permutations = 1;
    for (int i = 1; i <= passengerSeats; i++) {
        permutations *= i;
    }

    // Combinations of the passenger seats
    long combinations = 1;
    for (int i = 1; i <= emptySeats; i++) {
        combinations *= i;
    }

    double probability = (double)combinations / permutations;
    return probability;
}

public static double calculateProbability(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("n must be a positive integer");
    }

    double probability = 1.0 / n;

    for (int i = 1; i < n; i++) {
        probability = probability * (1.0 - 1.0 / n) + 1.0 / n;
    }

    return probability;
}

