public static int longestLine(int[][] mat) {
    int m = mat.length;
    int n = mat[0].length;
    int[][] directions = new int[][]{{0, 1}, {1, 0}, {1, 1}, {1, -1}};
    int maxLength = 0;
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            for (int[] direction : directions) {
                int length = 0;
                while (i + length * direction[0] < m && j + length * direction[1] < n && mat[i + length * direction[0]][j + length * direction[1]] == 1) {
                    length++;
                }
                maxLength = Math.max(maxLength, length);
            }
        }
    }
    return maxLength;
}

public static int longestLine(int[][] mat) {
    int maxLength = 0;
    for (int i = 0; i < mat.length; i++) {
        for (int j = 0; j < mat[0].length; j++) {
            if (mat[i][j] == 1) {
                maxLength = Math.max(maxLength, 1 + longestLineHelper(mat, i, j));
            }
        }
    }
    return maxLength;
}

private static int longestLineHelper(int[][] mat, int i, int j) {
    if (i < 0 || j < 0 || i >= mat.length || j >= mat[0].length || mat[i][j] == 0) {
        return 0;
    }
    mat[i][j] = 0;
    return 1 + longestLineHelper(mat, i + 1, j) + longestLineHelper(mat, i, j + 1)
            + longestLineHelper(mat, i - 1, j) + longestLineHelper(mat, i, j - 1);
}

public static int longestLine(int[][] mat) {
    int maxLength = 0;

    for (int i = 0; i < mat.length; i++) {
        for (int j = 0; j < mat[0].length; j++) {
            if (mat[i][j] == 1) {
                maxLength = Math.max(maxLength, horizontalLineLength(mat, i, j));
                maxLength = Math.max(maxLength, verticalLineLength(mat, i, j));
                maxLength = Math.max(maxLength, diagonalLineLength(mat, i, j));
                maxLength = Math.max(maxLength, antiDiagonalLineLength(mat, i, j));
            }
        }
    }

    return maxLength;
}

private static int horizontalLineLength(int[][] mat, int row, int col) {
    int length = 0;
    for (int i = col; i >= 0 && mat[row][i] == 1; i--) {
        length++;
    }
    for (int i = col + 1; i < mat[0].length && mat[row][i] == 1; i++) {
        length++;
    }
    return length;
}

private static int verticalLineLength(int[][] mat, int row, int col) {
    int length = 0;
    for (int i = row; i >= 0 && mat[i][col] == 1; i--) {
        length++;
    }
    for (int i = row + 1; i < mat.length && mat[i][col] == 1; i++) {
        length++;
    }
    return length;
}

private static int diagonalLineLength(int[][] mat, int row, int col) {
    int length = 0;
    for (int i = 1; row - i >= 0 && col - i >= 0 && mat[row - i][col - i] == 1; i++) {
        length++;
    }
    for (int i = 1; row + i < mat.length && col + i < mat[0].length && mat[row + i][col + i] == 1; i++) {
        length++;
    }
    return length;
}

private static int antiDiagonalLineLength(int[][] mat, int row, int col) {
    int length = 0;
    for (int i = 1; row - i >= 0 && col + i < mat[0].length && mat[row - i][col + i] == 1; i++) {
        length++;
    }
    for (int i = 1; row + i < mat.length && col - i >= 0 && mat[row + i][col - i] == 1; i++) {
        length++;
    }
    return length;
}

