private static int diagonalLine(int[][] mat, int i, int j) {
    int lineLength = 1;
    for (int k = i + 1, l = j + 1; k < mat.length && l < mat[0].length; k++, l++) {
        if (mat[k][l] == 1) {
            lineLength++;
