public static int squarePermutations(int[] A) {
    int n = A.length;
    int[][] dp = new int[n][n];
    int[][] cache = new int[n][n];
    for (int i = 0; i < n; i++) {
        dp[i][i] = 1;
    }
    for (int i = 0; i < n; i++) {
        for (int j = i + 1; j < n; j++) {
            int sq = (int) (Math.sqrt(A[i] + A[j]));
            if (sq * sq == A[i] + A[j]) {
                for (int k = 0; k < n; k++) {
                    cache[k][j] = dp[k][i] * dp[k][j];
                }
            }
            for (int k = 0; k < n; k++) {
                dp[k][j] = cache[k][j] % (1000000007);
            }
        }
    }
    int res = 0;
    for (int i = 0; i < n; i++) {
        res += dp[n - 1][i];
    }
    return res % 1000000007;
}

