public static int largestRectangleArea(int[] heights) {
    int maxArea = 0;
    Stack<Integer> stack = new Stack<>();
    stack.push(-1);
    for (int i = 0; i < heights.length; i++) {
        while (stack.peek() != -1 && heights[i] < heights[stack.peek()]) {
            int top = stack.pop();
            int area = heights[top] * (i - stack.peek() - 1);
            maxArea = Math.max(maxArea, area);
        }
        stack.push(i);
    }
    while (stack.peek() != -1) {
        int top = stack.pop();
        int area = heights[top] * (heights.length - stack.peek() - 1);
        maxArea = Math.max(maxArea, area);
    }
    return maxArea;
}

public static int largestRectangleArea(int[] heights) {
    int maxArea = 0;
    Deque<Integer> stack = new ArrayDeque<>();

    for (int i = 0; i <= heights.length; i++) {
        int currHeight = i < heights.length ? heights[i] : 0;
        if (stack.isEmpty() || currHeight >= heights[stack.peek()]) {
            stack.push(i);
        } else {
            int top = stack.pop();
            maxArea = Math.max(maxArea, heights[top] * (stack.isEmpty() ? i : i - stack.peek() - 1));
            i--;
        }
    }

    return maxArea;
}

