public static int[] diagonalOrder(int[][] mat) {
    int[] result = new int[mat.length * mat[0].length];
    int row = 0;
    int col = 0;
    int idx = 0;
    boolean up = true;
    while (row < mat.length && col < mat[0].length) {
        result[idx] = mat[row][col];
        if (up) {
            if (col == mat[0].length - 1) {
                row++;
                col--;
                up = false;
            } else if (row == mat.length - 1) {
                col++;
                up = true;
            } else {
                row++;
                col++;
            }
        } else {
            if (row == mat.length - 1) {
                row--;
                col++;
                up = true;
            } else if (col == 0) {
                row++;
                col++;
                up = false;
            } else {
                row--;
                col--;
            }
        }
        idx++;
    }
    return result;
}

