    }
    Arrays.sort(digits);
    int smallest = Integer.parseInt(String.valueOf(digits));
    if (smallest > n) {
        return smallest;
    }
    for (int i = 0; i < digits.length; i++) {
        for (int j = i + 1; j < digits.length; j++) {
            if (digits[i] == digits[j]) {
                digits[j] = Math.abs(digits[j] - 1);
            }
        }
    }
    smallest = Integer.parseInt(String.valueOf(digits));
    if (smallest > n) {
        return smallest;
    }
    return -1;
}

