public static int findSmallestInteger(int n) {
    // Convert the input integer to a string
    String num = String.valueOf(n);

    // Sort the digits in ascending order
    char[] digits = num.toCharArray();
    Arrays.sort(digits);

    // Check if the digits are in descending order
    for (int i = 0; i < digits.length - 1; i++) {
        if (digits[i] > digits[i + 1]) {
            // If not, swap the adjacent digits and check again
            char temp = digits[i];
            digits[i] = digits[i + 1];
            digits[i + 1] = temp;
        }
    }

    // If the digits are in descending order, return -1
    if (Arrays.equals(digits, num.toCharArray())) {
        return -1;
    }

    // Otherwise, return the rearranged integer
    return Integer.parseInt(new String(digits));
}

