public static List<String> centerSymmetricNumbers(int n) {
    List<String> symmetricNumbers = new ArrayList<>();

    // base case: if n is 1, return all center symmetric numbers with length 1
    if (n == 1) {
        symmetricNumbers.add("0");
        symmetricNumbers.add("1");
        symmetricNumbers.add("8");
        return symmetricNumbers;
    }

    // recursive case: if n is greater than 1, find all center symmetric numbers of length n-1
    List<String> smallerSymmetricNumbers = centerSymmetricNumbers(n-1);

    // iterate through each smaller symmetric number and add them to the symmetric numbers list
    for (String smallerSymmetricNumber : smallerSymmetricNumbers) {
        int num = Integer.parseInt(smallerSymmetricNumber);
        int reverse = Integer.parseInt(new StringBuilder(smallerSymmetricNumber).reverse().toString());
        if (num == reverse) {
            symmetricNumbers.add(smallerSymmetricNumber);
        }
    }

    // return the list of center symmetric numbers
    return symmetricNumbers;
}

