public static int findNthUglyNumber(int n) {
    if (n <= 0) {
        return -1;
    }
    int[] uglyArray = new int[n];
    int nextUglyIndex = 1;
    int nextMultiplicationFactor = 2;
    for (int i = 1; i < n; i++) {
        int nextUglyNumber = Math.min(2 * uglyArray[nextMultiplicationFactor - 1], Math.min(3 * uglyArray[nextMultiplicationFactor - 2], 5 * uglyArray[nextMultiplicationFactor - 3]));
        for (int j = nextMultiplicationFactor; uglyArray[j - 1] == nextUglyNumber / 2 || uglyArray[j - 2] == nextUglyNumber / 3 || uglyArray[j - 3] == nextUglyNumber / 5; j++);
        nextMultiplicationFactor = j;
        uglyArray[i] = nextUglyNumber;
    }
    return uglyArray[n - 1];
}

