public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    for (int i = 1; i <= 9; i++) {
        result.add(i);
    }
    for (int i = 1; i <= n - 9; i++) {
        if (i < 10) {
            result.add(10 * i);
        } else if (i < 100) {
            int digit1 = i / 10;
            int digit2 = i % 10;
            if (digit1 > digit2) {
                result.add(10 * digit1 + digit2);
            } else {
                result.add(10 * digit2 + digit1);
            }
        } else if (i < 1000) {
            int digit1 = i / 100;
            int digit2 = (i % 100) / 10;
            int digit3 = i % 10;
            if (digit1 > digit2) {
                if (digit2 > digit3) {
                    result.add(100 * digit1 + 10 * digit2 + digit3);
                } else {
                    if (digit1 > digit3) {
                        result.add(100 * digit1 + 10 * digit3 + digit2);
                    } else {
                        result.add(100 * digit3 + 10 * digit1 + digit2);
                    }
                }
            } else {
                if (digit2 > digit3) {
                    result.add(100 * digit2 + 10 * digit1 + digit3);
                } else {
                    if (digit2 > digit1) {
                        result.add(100 * digit2 + 10 * digit3 + digit1);
                    } else {
                        result.add(100 * digit1 + 10 * digit3 + digit2);
                    }
                }
            }
        } else {
            for (int j = 1; j <= i; j++) {
                result.add(j);
            }
        }
    }
    return result;
}

public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    for (int i = 1; i <= 9; i++) {
        result.add(i);
    }
    for (int i = 10; i <= n; i++) {
        int prev = result.get(result.size() - 1);
        if (prev * 10 <= n) {
            result.add(prev * 10);
        }
        int next = result.get(0);
        if (next % 10 != 0 && next < n) {
            result.add(0, next % 10);
        }
    }
    return result;
}

