public static int minPerfectSquareSum(int n) {
    int count = 0;
    int sum = 0;
    while (sum < n) {
        int perfectSquare = (int) Math.pow(count, 2);
        sum += perfectSquare;
        if (sum > n) {
            break;
        }
        count++;
    }
    return count;
}

public static int minPerfectSquareSum(int n) {
    int minNumPerfectSquares = Integer.MAX_VALUE;
    int currentNumPerfectSquares = 0;
    for (int i = 1; i * i <= n; i++) {
        if (n % (i * i) == 0) {
            currentNumPerfectSquares++;
            if (currentNumPerfectSquares < minNumPerfectSquares) {
                minNumPerfectSquares = currentNumPerfectSquares;
            }
        }
    }
    return minNumPerfectSquares;
}

public static int minPerfectSquareSum(int n) {
    int minSquares = 0;
    int i = 1;
    while (n > 0) {
        int currentSquare = i * i;
        if (currentSquare > n) {
            break;
        }
        minSquares++;
        n -= currentSquare;
        i++;
    }
    return minSquares;
}

public static int minPerfectSquareSum(int n) {
    int count = 0;
    int sqrt = (int) Math.sqrt(n);
    int current = 1;
    while (current <= sqrt) {
        int remaining = n - current * current;
        if (remaining <= 0) {
            count++;
            break;
        }
        current++;
    }
    if (remaining > 0) {
        count += remaining;
    }
    return count;
}

public static int minPerfectSquareSum(int n) {
    int count = 0;
    while (n > 0) {
        int sqrt = (int) Math.sqrt(n);
        count++;
        n -= sqrt * sqrt;
    }
    return count;
}

public static String reverseWords(String s) {
    String[] words = s.split(" ");
    for (int i = 0; i < words.length; i++) {
        String word = words[i];
        words[i] = new StringBuilder(word).reverse().toString();
    }
    return String.join(" ", words);
}

public static String reverseWords(String s) {
    String[] words = s.split(" ");
    StringBuilder reversed = new StringBuilder();
    for (String word : words) {
        StringBuilder wordReversed = new StringBuilder(word);
        while (wordReversed.length() > 0) {
            reversed.append(wordReversed.charAt(wordReversed.length() - 1));
            wordReversed.deleteCharAt(wordReversed.length() - 1);
        }
        reversed.append(" ");
    }
    return reversed.toString().trim();
}

public static String reverseWords(String s) {
    String[] words = s.split(" ");
    StringBuilder sb = new StringBuilder();
    for (int i = 0; i < words.length; i++) {
        String word = words[i];
        StringBuilder reversedWord = new StringBuilder();
        for (int j = word.length() - 1; j >= 0; j--) {
            reversedWord.append(word.charAt(j));
        }
        sb.append(reversedWord).append(" ");
    }
    return sb.toString().trim();
}

